const headers = $json.headers || {};
let body = $json.body ?? $json;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch { body = { text: body }; }
}
const text = body.text || body.transcript || '';
const forcedZone = body.forcedZone || headers['x-forced-zone'] || '';
const timezone = body.timezone || headers['x-timezone'] || 'Europe/Warsaw';
const now = body.now || headers['x-now'] || new Date().toISOString();
return [{ json: { text, forcedZone, timezone, now, source: body.source || 'static-pwa' } }];

