const content = $json.output_text || $json.text || $json.choices?.[0]?.message?.content || $json.output?.[0]?.content?.[0]?.text || '{}';
const parsed = typeof content === 'string' ? JSON.parse(content) : content;
const validZones = ['do', 'plan', 'delegate', 'delete'];
const task = parsed.task || {};
if (!validZones.includes(task.zone)) task.zone = $('Normalize Text Input').item.json.forcedZone || 'do';
if (!task.title) task.title = $('Normalize Text Input').item.json.text || 'Nowe zadanie';
const event = parsed.event || { create: false };
return [{ json: { task, event, transcript: $('Normalize Text Input').item.json.text } }];

const calendar = $('Google Calendar - Create Event').item?.json || {};
const original = $('Parse JSON').item.json;
return [{ json: { task: { ...original.task, calendarEventId: calendar.id || '', dueAt: original.task.dueAt || original.event.start || '' }, event: original.event, calendar, transcript: original.transcript } }];
